const H = require('./hgamebattle');

const CU = H.CU;
const TECHS = ['ShieldTech', 'MaterialTech', 'ComputerTech', 'MilitaryTech', 'MissileTech', 'LaserTech', 'IonTech', 'PlasmaTech', 'ProtonTech'];

// Unser Techstand: Kampfforschungen laut neuestem Snapshot (beim Bauen von combat-units.json übernommen).
const UNSER_TECHSTAND = { ...CU.forschung.neuesterSnapshot.stufen };

// Anteil, der nach dem Kampf NICHT sofort wieder da ist (Abschnitt 1/11): Boden ~70 %, Satelliten ~50 %, Minen ~20 % zurück.
const VERLUSTANTEIL = { Planetarverteidigung: 0.3, Festungsverteidigung: 0.3, Mutterschiffverteidigung: 0.3, Orbitalverteidigung: 0.5, Raumminen: 0.8 };

