    sieger: ergebnis.sieger,
    verlustwert: { verteidiger: verlustwert[0], angreifer: verlustwert[1] },
    verteidigungEffektiv: effektiv,
    beute,
    angriffSaldo: beute - verlustwert[1] - treibstoff,       // > 0: Angriff lohnt
    verteidigungSaldo: ergebnis.sieger === 1 ? -(effektiv + beute) : -effektiv,
